package com.simibubi.create.test;

import com.simibubi.create.*;
import com.simibubi.create.content.trains.track.*;
import it.unimi.dsi.fastutil.longs.Long2ObjectLinkedOpenHashMap;
import java.util.*;
import net.fabricmc.fabric.api.gametest.v1.GameTest;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.*;
import net.minecraft.world.*;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.*;
import net.minecraft.world.item.context.UseOnContext;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.BarrelBlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.properties.*;
import net.minecraft.world.level.chunk.*;
import net.minecraft.world.level.chunk.status.ChunkStatus;
import net.minecraft.world.phys.*;

/** Proposed native source pavement, real item/world transactions and genuine unavailable-frontier tests. */
public final class TrackPavingGameTests {
    static final String STRUCTURE="create_test:reservoir";
    static final BlockPos A=new BlockPos(5,9,6),B=new BlockPos(13,9,6);
    static BlockState rail(TrackShape shape){return AllBlocks.TRACK.defaultBlockState().setValue(TrackBlock.SHAPE,shape);}
    static void endpoint(GameTestHelper h,BlockPos pos,TrackShape shape){h.setBlock(pos.below(),Blocks.STONE);h.setBlock(pos,rail(shape));}
    static Player player(GameTestHelper h,Item pavement){var p=h.makeMockPlayer(GameType.SURVIVAL);p.setPos(Vec3.atBottomCenterOf(h.absolutePos(A)).add(0,1,2));var tracks=new ItemStack(AllBlocks.TRACK,64);tracks.set(DataComponents.CUSTOM_NAME,Component.literal("Original selected railway stock"));p.setItemInHand(InteractionHand.MAIN_HAND,tracks);p.getInventory().setItem(9,new ItemStack(AllBlocks.TRACK,64));if(pavement!=null){p.setItemInHand(InteractionHand.OFF_HAND,new ItemStack(pavement,64));var extra=new ItemStack(pavement,64);extra.set(DataComponents.CUSTOM_NAME,Component.literal("Original main pavement stock"));p.getInventory().setItem(10,extra);}return p;}
    static int count(Player p,Item item){int n=0;for(int i=0;i<p.getInventory().getNonEquipmentItems().size();i++)if(p.getInventory().getItem(i).is(item))n+=p.getInventory().getItem(i).getCount();if(p.getOffhandItem().is(item))n+=p.getOffhandItem().getCount();return n;}
    static InteractionResult click(GameTestHelper h,Player p,BlockPos local,float yaw){p.setYRot(yaw);p.setXRot(0);var pos=h.absolutePos(local);return p.getMainHandItem().getItem().useOn(new UseOnContext(p,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atBottomCenterOf(pos).add(0,.125,0),Direction.UP,pos,false)));}
    static TrackPlacement.PlacementInfo preview(GameTestHelper h,Player p,BlockPos to,float yaw,boolean maximise){p.setYRot(yaw);return TrackPlacement.preview(h.getLevel(),p,h.absolutePos(to),h.getBlockState(to),p.getMainHandItem(),p.getOffhandItem().is(AllBlocks.METAL_GIRDER.asItem()),maximise);}
    static Player straight(GameTestHelper h,Item pavement){endpoint(h,A,TrackShape.XO);endpoint(h,B,TrackShape.XO);var p=player(h,pavement);h.assertTrue(click(h,p,A,-90).consumesAction(),"Actual native source selection");return p;}
    static BezierConnection paidCurve(GameTestHelper h,boolean slope){var b=slope?new BlockPos(25,11,6):A.offset(8,0,8);endpoint(h,A,TrackShape.XO);endpoint(h,b,slope?TrackShape.XO:TrackShape.ZO);var p=player(h,null);h.assertTrue(click(h,p,A,slope?-90:180).consumesAction(),"Actual native curve selection");p.setSprinting(true);var info=preview(h,p,b,slope?-90:180,true);h.assertTrue(info.valid&&info.curve!=null,"Actual source input plans a genuine curve");h.assertTrue(click(h,p,b,slope?-90:180).consumesAction(),"Actual native paid curve placement");return h.getBlockEntity(A,TrackBlockEntity.class).getConnections().get(h.absolutePos(b));}
    static Map<BlockPos,BlockState> snapshot(GameTestHelper h,Collection<BlockPos> positions){var result=new LinkedHashMap<BlockPos,BlockState>();for(var pos:positions)result.put(pos,h.getLevel().getBlockState(pos));return result;}
    static void unchanged(GameTestHelper h,Map<BlockPos,BlockState> before){for(var entry:before.entrySet())h.assertTrue(h.getLevel().getBlockState(entry.getKey())==entry.getValue(),"Actual native cell unchanged at "+entry.getKey());}
    static int changed(Map<BlockPos,BlockState> before,GameTestHelper h,Block block){int n=0;for(var entry:before.entrySet())if(h.getLevel().getBlockState(entry.getKey()).getBlock()==block&&entry.getValue().getBlock()!=block)n++;return n;}

    @GameTest(structure=STRUCTURE)public void actualNativeStraightPreviewPublishesExactFreeFootprintAndLeavesWorldAndStockUntouched(GameTestHelper h){var p=straight(h,Items.STONE);var selection=p.getMainHandItem().get(AllDataComponents.TRACK_CONNECTING_FROM);var info=preview(h,p,B,-90,false);h.assertTrue(info.valid&&info.curve==null&&info.requiredTracks==7&&info.requiredPavement==25&&info.desiredPavement.size()==25&&info.pavingItem==Items.STONE&&info.hasRequiredPavement,"Nine-cell source straight spans both original endpoints and25actual free pavement cells");for(var pos:info.desiredPavement.keySet())h.assertTrue(h.getLevel().getBlockState(pos).isAir(),"Read-only intended native pavement remains air");h.assertTrue(count(p,AllBlocks.TRACK.asItem())==128&&count(p,Items.STONE)==128&&selection.equals(p.getMainHandItem().get(AllDataComponents.TRACK_CONNECTING_FROM))&&!h.getBlockState(A).getValue(TrackBlock.HAS_BE),"Preview never places native data, resets selection or spends real items");h.succeed();}
    @GameTest(structure=STRUCTURE)public void nativeActualStraightItemUseCommitsPavementAndUsesOtherMainStacksBeforeSelectedAndOffhand(GameTestHelper h){var p=straight(h,Items.STONE);var info=preview(h,p,B,-90,false);var name=p.getMainHandItem().get(DataComponents.CUSTOM_NAME);var pavingName=p.getInventory().getItem(10).get(DataComponents.CUSTOM_NAME);h.assertTrue(click(h,p,B,-90).consumesAction(),"Actual native source use commits complete paid straight");for(var pos:info.desiredPavement.keySet())h.assertTrue(h.getLevel().getBlockState(pos).is(Blocks.STONE),"Actual world contains intended source pavement");h.assertTrue(p.getMainHandItem().getCount()==64&&p.getMainHandItem().get(DataComponents.CUSTOM_NAME).equals(name)&&!p.getMainHandItem().has(AllDataComponents.TRACK_CONNECTING_FROM)&&p.getInventory().getItem(9).getCount()==64-info.requiredTracks&&p.getOffhandItem().getCount()==64&&p.getInventory().getItem(10).getCount()==64-info.requiredPavement&&p.getInventory().getItem(10).get(DataComponents.CUSTOM_NAME).equals(pavingName),"Pinned source debit order and original per-stack components survive native payment");h.succeed();}
    @GameTest(structure=STRUCTURE)public void actualSelectedStackExhaustionNeverMovesSelectionToAnUnrelatedNativeStack(GameTestHelper h){var p=straight(h,null);var info=preview(h,p,B,-90,false);var originalSelected=p.getMainHandItem();p.getMainHandItem().setCount(1);p.getInventory().setItem(9,new ItemStack(AllBlocks.TRACK,info.requiredTracks-1));var unrelated=new ItemStack(Items.DIAMOND,5);unrelated.set(DataComponents.CUSTOM_NAME,Component.literal("Unrelated five diamonds"));p.getInventory().setItem(10,unrelated);h.assertTrue(click(h,p,B,-90).consumesAction()&&p.getMainHandItem().isEmpty()&&!originalSelected.has(AllDataComponents.TRACK_CONNECTING_FROM)&&p.getInventory().getItem(9).isEmpty()&&p.getInventory().getItem(10)==unrelated&&!unrelated.has(AllDataComponents.TRACK_CONNECTING_FROM),"Actual source stock exhausts only after other main stock, with no fabricated selection or unrelated replacement");h.succeed();}
    @GameTest(structure=STRUCTURE)public void insufficientActualPavementRejectsEntireNativeStraightBeforeAnyWorldOrTrackDebit(GameTestHelper h){var p=straight(h,Items.STONE);p.getInventory().setItem(10,ItemStack.EMPTY);p.getOffhandItem().setCount(1);var selection=p.getMainHandItem().get(AllDataComponents.TRACK_CONNECTING_FROM);var info=preview(h,p,B,-90,false);var all=new LinkedHashSet<>(info.desiredPavement.keySet());all.addAll(info.desiredTracks.keySet());var before=snapshot(h,all);h.assertTrue(!info.valid&&info.hasRequiredTracks&&!info.hasRequiredPavement&&"create.track.not_enough_pavement".equals(info.message)&&click(h,p,B,-90)==InteractionResult.FAIL,"Same native preview/use require actual full intended pavement stock");unchanged(h,before);h.assertTrue(count(p,AllBlocks.TRACK.asItem())==128&&p.getOffhandItem().getCount()==1&&selection.equals(p.getMainHandItem().get(AllDataComponents.TRACK_CONNECTING_FROM)),"Failed full payment preflight preserves exact real inventory and selection");h.succeed();}
    @GameTest(structure=STRUCTURE)public void insufficientActualTrackStockCannotLeaveAnyFreePavementBehind(GameTestHelper h){var p=straight(h,Items.STONE);p.getMainHandItem().setCount(1);p.getInventory().setItem(9,ItemStack.EMPTY);var info=preview(h,p,B,-90,false);var before=snapshot(h,info.desiredPavement.keySet());h.assertTrue(!info.valid&&!info.hasRequiredTracks&&"create.track.not_enough_tracks".equals(info.message)&&click(h,p,B,-90)==InteractionResult.FAIL,"Actual complete track requirement precedes every pavement write");unchanged(h,before);h.assertTrue(count(p,Items.STONE)==128&&p.getMainHandItem().getCount()==1,"No pavement or track material is spent on failed native construction");h.succeed();}
    @GameTest(structure=STRUCTURE)public void realTrackObstructionPreventsEveryPavementPlacementAndPreservesNamedCargo(GameTestHelper h){var p=straight(h,Items.STONE);var middle=A.east(4);h.setBlock(middle,Blocks.BARREL);var barrel=h.getBlockEntity(middle,BarrelBlockEntity.class);var cargo=new ItemStack(Items.DIAMOND,7);cargo.set(DataComponents.CUSTOM_NAME,Component.literal("Seven original obstruction diamonds"));barrel.setItem(0,cargo);h.assertTrue(click(h,p,B,-90)==InteractionResult.FAIL&&h.getBlockEntity(middle,BarrelBlockEntity.class)==barrel&&barrel.getItem(0)==cargo&&count(p,Items.STONE)==128&&count(p,AllBlocks.TRACK.asItem())==128,"Real source full track preflight precedes all pavement and preserves original native BE/cargo identity");h.assertTrue(h.getLevel().getBlockState(h.absolutePos(A.offset(0,-1,1))).isAir(),"No partial free pavement appears before actual obstructed track");h.succeed();}
    @GameTest(structure=STRUCTURE)public void nativePavementSkipsOriginalBarrelCargoAndChargesOnlyActuallyNewCells(GameTestHelper h){var p=straight(h,Items.STONE);var first=preview(h,p,B,-90,false);var at=first.desiredPavement.keySet().iterator().next();h.getLevel().setBlockAndUpdate(at,Blocks.BARREL.defaultBlockState());var barrel=(BarrelBlockEntity)h.getLevel().getBlockEntity(at);var cargo=new ItemStack(Items.EMERALD,9);cargo.set(DataComponents.CUSTOM_NAME,Component.literal("Nine original pavement emeralds"));barrel.setItem(0,cargo);var info=preview(h,p,B,-90,false);h.assertTrue(info.valid&&info.requiredPavement==first.requiredPavement-1&&!info.desiredPavement.containsKey(at)&&click(h,p,B,-90).consumesAction(),"Pinned source skips actual occupied pavement cells without charging for them");h.assertTrue(h.getLevel().getBlockEntity(at)==barrel&&barrel.getItem(0)==cargo&&count(p,Items.STONE)==128-info.requiredPavement,"Actual existing BE, cargo and exact paid pavement stock survive native construction");h.succeed();}
    @GameTest(structure=STRUCTURE)public void genuineOffhandEntityBlockAndEmptyCollisionItemCannotBecomePavement(GameTestHelper h){var p=straight(h,Items.BARREL);var barrel=preview(h,p,B,-90,false);h.assertTrue(barrel.valid&&barrel.pavingItem==null&&barrel.requiredPavement==0&&barrel.desiredPavement.isEmpty(),"Actual native EntityBlock inventory cannot be paved");p.setItemInHand(InteractionHand.OFF_HAND,new ItemStack(Items.TORCH,64));var torch=preview(h,p,B,-90,false);h.assertTrue(torch.valid&&torch.pavingItem==null&&torch.requiredPavement==0&&torch.desiredPavement.isEmpty()&&count(p,AllBlocks.TRACK.asItem())==128,"Real empty collision shapes are rejected by source pavement selection without mutation");h.succeed();}
    @GameTest(structure=STRUCTURE)public void actualNativeStraightSlabsBecomeDoubleAndRequireTwoItemsPerNewCell(GameTestHelper h){var p=straight(h,Items.STONE_SLAB);var info=preview(h,p,B,-90,false);h.assertTrue(info.valid&&info.requiredPavement==info.desiredPavement.size()*2&&info.requiredPavement==50&&click(h,p,B,-90).consumesAction(),"Pinned source cardinal slab pavement pays two slabs per actual new native cell");for(var at:info.desiredPavement.keySet())h.assertTrue(h.getLevel().getBlockState(at).getValue(SlabBlock.TYPE)==SlabType.DOUBLE,"Actual straight source slab is double");h.assertTrue(count(p,Items.STONE_SLAB)==128-info.requiredPavement,"Native slab material ledger matches source plan");h.succeed();}
    @GameTest(structure=STRUCTURE)public void sourceSameBlockRuleLeavesExistingBottomSlabAndDoesNotChargeOrUpgradeIt(GameTestHelper h){var p=straight(h,Items.STONE_SLAB);var first=preview(h,p,B,-90,false);var at=first.desiredPavement.keySet().iterator().next();var bottom=Blocks.STONE_SLAB.defaultBlockState().setValue(SlabBlock.TYPE,SlabType.BOTTOM);h.getLevel().setBlockAndUpdate(at,bottom);var info=preview(h,p,B,-90,false);h.assertTrue(info.requiredPavement==first.requiredPavement-2&&!info.desiredPavement.containsKey(at)&&click(h,p,B,-90).consumesAction()&&h.getLevel().getBlockState(at)==bottom,"Pinned source same-block identity preserves existing slab type rather than silently upgrading it or consuming extra stock");h.succeed();}
    @GameTest(structure=STRUCTURE)public void realNativeWaterIsRetainedBySourceSlabPavement(GameTestHelper h){var p=straight(h,Items.STONE_SLAB);var initial=preview(h,p,B,-90,false);var at=initial.desiredPavement.keySet().iterator().next();h.getLevel().setBlockAndUpdate(at,Blocks.WATER.defaultBlockState());var info=preview(h,p,B,-90,false);h.assertTrue(info.valid&&info.desiredPavement.get(at).getValue(BlockStateProperties.WATERLOGGED)&&click(h,p,B,-90).consumesAction()&&h.getLevel().getBlockState(at).getValue(BlockStateProperties.WATERLOGGED),"Actual native source waterlogging survives simulation and real slab construction");h.succeed();}
    @GameTest(structure=STRUCTURE)public void nativeDiagonalSourceFootprintContainsActualGapFillersAndPaysEachCellOnce(GameTestHelper h){var start=h.absolutePos(new BlockPos(5,8,5));var visited=new HashSet<BlockPos>();int preview=TrackPaver.paveStraight(h.getLevel(),start,new Vec3(1,0,1),5,Blocks.STONE,true,visited);h.assertTrue(preview==23&&visited.size()==23&&visited.contains(start.east())&&visited.contains(start.south())&&visited.contains(start.offset(3,0,4)),"Pinned source diagonal normal and0.45float fillers produce23distinct actual cells");for(var pos:visited)h.assertTrue(h.getLevel().getBlockState(pos).isAir(),"Native source simulation changes no footprint cell");int paid=TrackPaver.paveStraight(h.getLevel(),start,new Vec3(1,0,1),5,Blocks.STONE,false,new HashSet<>());h.assertTrue(paid==23,"Real native source API matches exact simulated footprint cost");for(var pos:visited)h.assertTrue(h.getLevel().getBlockState(pos).is(Blocks.STONE),"Actual source gap filler cell placed");h.succeed();}
    @GameTest(structure=STRUCTURE)public void nativeWallPavementUsesOnlyActualSideLinesAndNeverFillsCenter(GameTestHelper h){var p=straight(h,Items.COBBLESTONE_WALL);var info=preview(h,p,B,-90,false);h.assertTrue(info.valid&&info.requiredPavement==18&&info.desiredPavement.size()==18&&click(h,p,B,-90).consumesAction(),"Native wall-like source pavement contains exactly two nine-cell side lines");for(int i=1;i<8;i++)h.assertTrue(h.getLevel().getBlockState(h.absolutePos(A.east(i).below())).isAir(),"Source wall-like pavement leaves genuine center empty");h.succeed();}
    @GameTest(structure=STRUCTURE)public void actualNativeGirderStraightUsesSourceAxisAndPaysNoImaginaryCurveBeams(GameTestHelper h){var p=straight(h,AllBlocks.METAL_GIRDER.asItem());var info=preview(h,p,B,-90,false);h.assertTrue(info.valid&&info.curve==null&&info.requiredGirders==18&&info.requiredPavement==18&&click(h,p,B,-90).consumesAction(),"Actual source girder straight pays only real side beams");for(var pos:info.desiredPavement.keySet()){var state=h.getLevel().getBlockState(pos);h.assertTrue(state.is(AllBlocks.METAL_GIRDER)&&state.getValue(com.simibubi.create.content.decoration.girder.GirderBlock.AXIS)==Direction.Axis.X&&state.getValue(com.simibubi.create.content.decoration.girder.GirderBlock.X),"Native actual cardinal girder keeps source axis and beam state");}h.assertTrue(count(p,AllBlocks.METAL_GIRDER.asItem())==128-18,"No curve girder cost was fabricated on a real straight");h.succeed();}
    @GameTest(structure=STRUCTURE)public void realCurveGirdersIncludeStraightSupportsAndChargeActualCurveBeamCostExactlyOnce(GameTestHelper h){var target=A.offset(8,0,8);endpoint(h,A,TrackShape.XO);endpoint(h,target,TrackShape.ZO);var p=player(h,AllBlocks.METAL_GIRDER.asItem());click(h,p,A,180);p.setSprinting(true);var info=preview(h,p,target,180,true);h.assertTrue(info.valid&&info.curve!=null&&info.requiredPavement==info.desiredPavement.size()+info.curve.getGirderItemCost()&&info.desiredPavement.size()==4&&info.requiredGirders==info.requiredPavement,"Actual source curve pays four genuine straight side supports and exactly one beam quantity");h.assertTrue(click(h,p,target,180).consumesAction()&&count(p,AllBlocks.METAL_GIRDER.asItem())==128-info.requiredPavement,"Real native curve has no duplicate beam debit");h.succeed();}
    @GameTest(structure=STRUCTURE)public void duplicateActualCurveNeverChargesExistingBeamsOrExistingPavementAgain(GameTestHelper h){var target=A.offset(8,0,8);endpoint(h,A,TrackShape.XO);endpoint(h,target,TrackShape.ZO);var p=player(h,AllBlocks.METAL_GIRDER.asItem());click(h,p,A,180);p.setSprinting(true);h.assertTrue(click(h,p,target,180).consumesAction(),"First actual source curve construction");int tracks=count(p,AllBlocks.TRACK.asItem()),girders=count(p,AllBlocks.METAL_GIRDER.asItem());click(h,p,A,180);var info=preview(h,p,target,180,true);h.assertTrue(info.valid&&info.requiredTracks==0&&info.requiredPavement==0&&info.requiredGirders==0&&click(h,p,target,180).consumesAction()&&count(p,AllBlocks.TRACK.asItem())==tracks&&count(p,AllBlocks.METAL_GIRDER.asItem())==girders,"Actual existing reciprocal construction is idempotent for both real supports and curve beam material");h.succeed();}
    @GameTest(structure=STRUCTURE)public void genuineNativeFullBlockCurveRetainsPinnedTwoItemsPerCellSourceQuirk(GameTestHelper h){var curve=paidCurve(h,false);var seen=new HashSet<BlockPos>();int simulated=TrackPaver.paveCurve(h.getLevel(),curve,Blocks.STONE,true,seen);var before=snapshot(h,seen);h.assertTrue(simulated>0&&simulated==2*seen.stream().filter(pos->before.get(pos).canBeReplaced()&&!before.get(pos).is(Blocks.STONE)).count(),"Pinned source charges two ordinary full blocks per free curve pavement cell");int actual=TrackPaver.paveCurve(h.getLevel(),curve,Blocks.STONE,false,new HashSet<>());h.assertTrue(actual==simulated&&actual==2*changed(before,h,Blocks.STONE),"Real native source API preserves that explicit quantity quirk rather than changing it silently");h.succeed();}
    @GameTest(structure=STRUCTURE)public void genuineNativeSlopedCurvePavementUsesPairedTopBottomSlabsAndExactDoubleQuantities(GameTestHelper h){var curve=paidCurve(h,true);var seen=new HashSet<BlockPos>();int quantity=TrackPaver.paveCurve(h.getLevel(),curve,Blocks.STONE_SLAB,true,seen);var before=snapshot(h,seen);h.assertTrue(quantity>0&&TrackPaver.paveCurve(h.getLevel(),curve,Blocks.STONE_SLAB,false,new HashSet<>())==quantity,"Actual native source sloped slab simulation and commit agree");int bottom=0,top=0,paid=0;for(var entry:before.entrySet()){var state=h.getLevel().getBlockState(entry.getKey());if(!state.is(Blocks.STONE_SLAB)||entry.getValue().is(Blocks.STONE_SLAB))continue;var type=state.getValue(SlabBlock.TYPE);paid+=type==SlabType.DOUBLE?2:1;if(type==SlabType.BOTTOM){bottom++;h.assertTrue(h.getLevel().getBlockState(entry.getKey().below()).is(Blocks.STONE_SLAB)&&h.getLevel().getBlockState(entry.getKey().below()).getValue(SlabBlock.TYPE)==SlabType.TOP,"Source upper bottom slab has its genuine lower top slab");}if(type==SlabType.TOP)top++;}h.assertTrue(bottom>0&&top==bottom&&paid==quantity,"Real source fractional height chooses actual paired halves and double-cell item quantities");h.succeed();}
    @GameTest(structure=STRUCTURE)public void genuineNativeWallCurvePavingIntentionallyPlacesAndCostsNothing(GameTestHelper h){var curve=paidCurve(h,false);var seen=new HashSet<BlockPos>();h.assertTrue(TrackPaver.paveCurve(h.getLevel(),curve,Blocks.COBBLESTONE_WALL,true,seen)==0&&seen.isEmpty()&&TrackPaver.paveCurve(h.getLevel(),curve,Blocks.COBBLESTONE_WALL,false,new HashSet<>())==0,"Pinned source wall curve has no solid block pavement or invented cost");h.succeed();}
    @GameTest(structure=STRUCTURE)public void actualMissingPavementChunkRejectsWholePlanWithoutLoadingItOrSpendingNativeInventory(GameTestHelper h){
        int z=15-(h.absolutePos(BlockPos.ZERO).getZ()&15);var a=new BlockPos(5,9,z);var b=a.east(8);endpoint(h,a,TrackShape.XO);endpoint(h,b,TrackShape.XO);var p=player(h,Items.STONE);click(h,p,a,-90);var full=preview(h,p,b,-90,false);h.assertTrue(full.valid,"Complete genuine native terrain initially allows source paving");var trackChunks=new HashSet<ChunkPos>();for(var at:full.desiredTracks.keySet())trackChunks.add(ChunkPos.containing(at));var absent=full.desiredPavement.keySet().stream().filter(at->!trackChunks.contains(ChunkPos.containing(at))).findFirst().orElseThrow();var all=new LinkedHashSet<>(full.desiredPavement.keySet());all.addAll(full.desiredTracks.keySet());var before=snapshot(h,all);var selection=p.getMainHandItem().get(AllDataComponents.TRACK_CONNECTING_FROM);
        unavailable(h,absent,h.absolutePos(a),()->{var missing=preview(h,p,b,-90,false);h.assertTrue(!missing.valid&&"create.track.unloaded".equals(missing.message)&&click(h,p,b,-90)==InteractionResult.FAIL&&count(p,AllBlocks.TRACK.asItem())==128&&count(p,Items.STONE)==128&&selection.equals(p.getMainHandItem().get(AllDataComponents.TRACK_CONNECTING_FROM)),"Actual source requires genuine pavement terrain, not only loaded rail endpoints");});unchanged(h,before);h.succeed();
    }
    @SuppressWarnings("unchecked")static void unavailable(GameTestHelper h,BlockPos absent,BlockPos present,Runnable body){
        var source=h.getLevel().getChunkSource();var chunk=source.getChunkNow(absent.getX()>>4,absent.getZ()>>4);h.assertTrue(chunk!=null&&!ChunkPos.containing(absent).equals(ChunkPos.containing(present)),"Actual native fixture chunks begin available and distinct");
        try{var field=ChunkMap.class.getDeclaredField("visibleChunkMap");field.setAccessible(true);var original=(Long2ObjectLinkedOpenHashMap<ChunkHolder>)field.get(source.chunkMap);var temporary=original.clone();temporary.remove(ChunkPos.pack(absent.getX()>>4,absent.getZ()>>4));var pf=ServerChunkCache.class.getDeclaredField("lastChunkPos");var sf=ServerChunkCache.class.getDeclaredField("lastChunkStatus");var cf=ServerChunkCache.class.getDeclaredField("lastChunk");pf.setAccessible(true);sf.setAccessible(true);cf.setAccessible(true);var positions=(long[])pf.get(source);var statuses=(ChunkStatus[])sf.get(source);var chunks=(ChunkAccess[])cf.get(source);var oldP=positions.clone();var oldS=statuses.clone();var oldC=chunks.clone();var clear=ServerChunkCache.class.getDeclaredMethod("clearCache");clear.setAccessible(true);
            try{field.set(source.chunkMap,temporary);clear.invoke(source);h.assertTrue(source.getChunkNow(absent.getX()>>4,absent.getZ()>>4)==null&&source.getChunkNow(present.getX()>>4,present.getZ()>>4)!=null,"Actual native availability exposes only genuine missing pavement frontier");body.run();h.assertTrue(source.getChunkNow(absent.getX()>>4,absent.getZ()>>4)==null,"No paving operation forces the missing native chunk");}finally{field.set(source.chunkMap,original);System.arraycopy(oldP,0,positions,0,positions.length);System.arraycopy(oldS,0,statuses,0,statuses.length);System.arraycopy(oldC,0,chunks,0,chunks.length);}h.assertTrue(field.get(source.chunkMap)==original&&source.getChunkNow(absent.getX()>>4,absent.getZ()>>4)==chunk,"Exact original native chunk map identity/order and cache arrays restored synchronously");
        }catch(ReflectiveOperationException error){throw new AssertionError("Native26.3 real chunk availability fixture changed",error);}
    }
}
